import sys
from collections import defaultdict, deque

def max_matching(n, edges):
    # Create adjacency list for the graph
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)

    # Initialize match array
    match = [-1] * (n + 1)

    def bfs(start):
        # Initialize distance array
        dist = [-1] * (n + 1)
        queue = deque()
        queue.append(start)
        dist[start] = 0

        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if match[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
                elif dist[match[v]] == -1:
                    dist[match[v]] = dist[u] + 2
                    queue.append(match[v])

        return any(d != -1 for d in dist[1:])

    def dfs(u):
        for v in adj[u]:
            if dist[v] == dist[u] + 1:
                dist[v] = -1
                if match[v] == -1 or dfs(match[v]):
                    match[v] = u
                    match[u] = v
                    return True
        return False

    for u in range(1, n + 1):
        if match[u] == -1:
            dist = [-1] * (n + 1)
            if bfs(u):
                for u in range(1, n + 1):
                    if match[u] == -1:
                        dfs(u)

    return sum(1 for m in match if m != -1) // 2

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])
    preferences = list(map(int, data[2:]))

    edges = [(i + 1, preferences[i]) for i in range(n)]

    result = max_matching(n, edges)
    print(min(result, k))

if __name__ == "__main__":
    main()
